# Draft questions, part A: Create and Evaluate gaps.
# Each check sets `vals` (one value per option, in option order) and `flags` (does option i satisfy the question?).
# The runner requires exactly one True flag and that it sits on the keyed option.
T = {
 'A2': 'Mathematics Investigation & Modeling', 'B1': 'College & Advanced Algebra', 'B2': 'Trigonometry',
 'B3': 'Plane & Solid Geometry', 'B4': 'Logic & Set Theory', 'B5': 'Statistics & Probability',
 'B6': 'Analytic Geometry', 'B7': 'Calculus', 'B8': 'Arithmetic & Number Theory', 'B9': 'Mathematics of Investment',
 'C1': 'Strategies in Teaching Mathematics', 'C2': 'Assessment in Mathematics',
 'C3': 'Research in Teaching Mathematics', 'C4': 'Technology in Mathematics Teaching'}

def D(code, gap, bloom, diff, q, opts, ans, why, check=None):
    return dict(code=code, gap=gap, bloom=bloom, difficulty=diff, question=q, choices=opts, answer='ABCD'.index(ans), explanation=why, check=check)

